import { Component, effect, inject, input, signal, untracked } from '@angular/core';
import { DashboardApi, DashboardView } from '../../core/dashboard';
import { Session } from '../../core/session';
import { StatusSummary } from '../summary/summary';

// The steward's dashboard, over the sheet and all its descendants: their PENDING claims, REVIEW claims and overdue claims that count, as
// the store holds them now. The cells are empty for a user who is not a steward, and while an as-of date is set. Re-read on every sheet load
// and whenever the sheet's claims or figures move.
@Component({
  selector: 'app-dashboard',
  template: `
    <section aria-label="Steward dashboard">
      <p>Pending claims <strong data-testid="dash-pending-count">{{ view()?.pendingCount ?? '' }}</strong></p>
      <p>Claims in review <strong data-testid="dash-review-count">{{ view()?.reviewCount ?? '' }}</strong></p>
      <p>Overdue claims <strong data-testid="dash-overdue-count">{{ view()?.overdueCount ?? '' }}</strong></p>
    </section>
  `,
})
export class Dashboard {
  private readonly session = inject(Session);
  private readonly api = inject(DashboardApi);

  /** The sheet's claim counts by status and its overdue-total as shown: a move in either re-reads the dashboard. */
  readonly statuses = input.required<StatusSummary[]>();
  readonly overdueTotal = input.required<string>();

  protected readonly view = signal<DashboardView | null>(null);
  /** Counts reads, so only the answer to the latest one is shown. */
  private reads = 0;

  constructor() {
    // Every sheet load clears the counts shown and re-reads them.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.view.set(null);
        if (sheet) void this.reload(sheet);
      });
    });
    // A move in the sheet's today, its as-of date, the signed-in user, or its claims re-reads them.
    effect(() => {
      this.session.today();
      this.session.asOf();
      this.session.user();
      this.statuses();
      this.overdueTotal();
      untracked(() => {
        const sheet = this.session.sheet();
        if (sheet) void this.reload(sheet);
      });
    });
  }

  private async reload(sheet: string): Promise<void> {
    const read = ++this.reads;
    try {
      const view = await this.api.get(sheet);
      if (read === this.reads && this.session.sheet() === sheet) this.view.set(view);
    } catch {
      // Left as it was: the next load or change reads them again.
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/**
 * A steward's dashboard over the sheet: how many claims are PENDING, how many in REVIEW, and how many
 * of those that count are overdue. Every count is null for a user who is not a steward.
 */
export interface DashboardView {
  pendingCount: number | null;
  reviewCount: number | null;
  overdueCount: number | null;
}

// The steward's dashboard, read from the store for the signed-in user.
@Injectable({ providedIn: 'root' })
export class DashboardApi {
  private readonly http = inject(HttpClient);

  get(sheet: string): Promise<DashboardView> {
    return firstValueFrom(this.http.get<DashboardView>(`/api/sheets/${encodeURIComponent(sheet)}/dashboard`));
  }
}

    /** What the screen is told about the steward's dashboard: the counts, all null for a user who is not a steward. */
    public record DashboardView(Long pendingCount, Long reviewCount, Long overdueCount) {
    }

    private final DashboardService service;

    public DashboardController(DashboardService service) {
        this.service = service;
    }

    /**
     * The sheet's steward dashboard as it stands now, for the signed-in user; empty while an as-of date
     * is set, as the dashboard shows only the sheet as it stands now; its figures read as if the sheet's
     * today were the preview date while one is set.
     */
    @GetMapping("/{id}/dashboard")
    public DashboardView dashboard(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf,
            @RequestHeader(value = PreviewDate.HEADER, required = false) String preview) {
        if (AsOfGuard.date(asOf) != null) {
            return new DashboardView(null, null, null);
        }
        return service.of(id, SignedIn.name(user), PreviewDate.date(preview))
                .map(d -> new DashboardView(d.pendingCount(), d.reviewCount(), d.overdueCount()))
                .orElse(new DashboardView(null, null, null));
    }
}
/**
 * The as-of date a user's screen shows the sheet as of, sent in the {@link #HEADER} header (yyyy-mm-dd)
 * on every request while it is set. Every change asked for while it is set is refused: any request
 * other than a read, or the loading of the sheet, is turned away before it reaches its handler, so it
 * writes nothing and audits nothing.
 */
@Configuration
public class AsOfGuard implements WebMvcConfigurer, HandlerInterceptor {

    public static final String HEADER = "X-As-Of";

    /** The as-of date from the header's value; null when none is set. */
    public static LocalDate date(String header) {
        String text = header == null ? "" : header.trim();
        try {
            return text.isEmpty() ? null : LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not an as-of date: " + text);
        }
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
            return true;
        }
        if (date(request.getHeader(HEADER)) != null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The sheet is shown as of a date: nothing may change until the as-of date is cleared.");
        }
        return true;
    }
}

